INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27301, '1 Corinthians 4:1', '1 Corinthians', 4, 1, '&nbsp;تاسو مونږ د مسيح خادِمان او د خُدائ پاک د رازونو ساتونکى وګڼئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27302, '1 Corinthians 4:2', '1 Corinthians', 4, 2, '&nbsp;اوس ساتونکو ته په کار دى چې هغوئ اعتبارى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27303, '1 Corinthians 4:3', '1 Corinthians', 4, 3, '&nbsp;خو زما دپاره دا ډېره وړه خبره ده چې تاسو يا بل انسانى عدالت دې زما جاج واخلى، بلکې زۀ په خپله هم د ځان جاج نۀ اخلم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27304, '1 Corinthians 4:4', '1 Corinthians', 4, 4, '&nbsp;زۀ په خپله په خپل ځان کښې د څۀ عېب احساس نۀ کوم خو د دې مطلب دا نۀ دے چې زۀ بې‌عېبه يم. ځکه چې مالِک زما جاج اخلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27305, '1 Corinthians 4:5', '1 Corinthians', 4, 5, '&nbsp;نو په دې وجه د مقرر شوى وخت نه وړاندې فېصله مۀ کوئ، د مالِک د راتلو تر وخته انتظار وکړئ. هغه به د تيارې پټې خبرې رڼا ته څرګندې کړى او د زړۀ مقصدونه به راښکاره کړى. په هغه وخت کښې څوک چې د څومره تعريف قابل وى خُدائ پاک به دومره د هغۀ تعريف وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27306, '1 Corinthians 4:6', '1 Corinthians', 4, 6, '&nbsp;اے وروڼو او خوېندو، ما په دغه خبرو کښې د خپل ځان او د اپولوس ذکر د مِثال په طور وکړو د دې دپاره چې تاسو زمونږ په وسيله د دې خبرو مطلب زده کړئ، د ليکل شوى کلام نه زيات څۀ مۀ وايئ، او د يو مشر صِفت او د بل غېبت مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27307, '1 Corinthians 4:7', '1 Corinthians', 4, 7, '&nbsp;تاسو هيچا هم په بل باندې بهتر کړى نۀ يئ. او تاسو سره چې څۀ دى هغه خُدائ پاک درکړى دى. او بيا چې هر څۀ خُدائ پاک درکړى دى نو بيا په څۀ خبره فخر کوئ لکه چې هغۀ نۀ وى درکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27308, '1 Corinthians 4:8', '1 Corinthians', 4, 8, '&nbsp;ستاسو په خيال تاسو اوس هغه هر څۀ حاصل کړل څۀ چې تاسو غوښتل، تاسو اوس مالداره شوى يئ، زمونږ نه بغېر تاسو بادشاهى کوئ، په حقيقت کښې زما خواهش وو چې تاسو بادشاهان شئ نو چې مونږ هم درسره بادشاهى وکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27309, '1 Corinthians 4:9', '1 Corinthians', 4, 9, '&nbsp;خو په اصل کښې خُدائ پاک مونږ رسولان د ټولو نه لاندې کړُو او د هغه خلقو په شان يې پېش کړُو په چا چې د مرګ حکم شوے وى، ولې چې مونږ د ټولې دُنيا، يعنې فرښتو او د بنى آدمو په وړاندې يوه تماشه شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27310, '1 Corinthians 4:10', '1 Corinthians', 4, 10, '&nbsp;مونږ د مسيح په خاطر بې‌وقوفان يُو، خو تاسو په مسيح کښې هوښيار يئ. مونږ کمزورى يُو خو تاسو زورَور يئ. تاسو عزتمند يئ او مونږ سپک يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27311, '1 Corinthians 4:11', '1 Corinthians', 4, 11, '&nbsp;په دې موجوده وخت کښې مونږ اوږى، تږى يُو، کپړې مو زړې دى او وهلے شوى يُو او بې‌کوره يُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27312, '1 Corinthians 4:12', '1 Corinthians', 4, 12, '&nbsp;او مونږ په خپلو لاسونو خوارى کوُو. خلق په مونږ بد وائى، مونږ ورته دُعا کوُو، کله چې مو زوروى، مونږ يې زغمو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27313, '1 Corinthians 4:13', '1 Corinthians', 4, 13, '&nbsp;څوک چې مونږ بدناموى، هغوئ ته په مينې سره خواست کوُو. مونږ تر ننه پورې د دُنيا د ډيران او د ګند په شان پاتې شوى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27314, '1 Corinthians 4:14', '1 Corinthians', 4, 14, '&nbsp;زۀ دا خبرې ستاسو د شرمولو دپاره نۀ ليکم بلکې تاسو ته د خپلو خوږو بچو په شان نصيحت کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27315, '1 Corinthians 4:15', '1 Corinthians', 4, 15, '&nbsp;ځکه چې کۀ په مسيح کښې ستاسو اُستاذان بې‌شمېره هم وى خو بيا هم ستاسو روحانى پلار يو دے، او د زيرى په وسيله زۀ په عيسىٰ مسيح کښې ستاسو پلار شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27316, '1 Corinthians 4:16', '1 Corinthians', 4, 16, '&nbsp;نو زۀ تاسو ته زارى کوم چې زما په نقش قدم شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27317, '1 Corinthians 4:17', '1 Corinthians', 4, 17, '&nbsp;په دې وجه ما تاسو ته تيموتيوس درولېږلو، هغه په مالِک کښې زما خوږ او وفادار زوئ دے، چې تاسو ته په مسيح کښې زما هغه طريقې دريادې کړى چې زۀ يې هغوئ ته په هر ځائ او په هر جماعت کښې تعليم ورکوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27318, '1 Corinthians 4:18', '1 Corinthians', 4, 18, '&nbsp;خو تاسو کښې ځينې داسې مغروره شول چې زۀ ګنې تاسو ته درتلے نۀ شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27319, '1 Corinthians 4:19', '1 Corinthians', 4, 19, '&nbsp;خو کۀ مالِک وغوښتل نو زۀ به تاسو له زر درشم او زۀ به نۀ صرف د هغه مغروره خلقو خبرې بلکې د هغوئ روحانى قدرت هم معلوم کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27320, '1 Corinthians 4:20', '1 Corinthians', 4, 20, '&nbsp;ځکه چې د خُدائ پاک بادشاهت په تشو خبرو نه، بلکې د هغۀ په قدرت ولاړ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27321, '1 Corinthians 4:21', '1 Corinthians', 4, 21, '&nbsp;نو تاسو څۀ وايئ چې زۀ تاسو ته کوتک په لاس يا په مينه د نرمۍ په روح کښې درشم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27322, '1 Corinthians 5:1', '1 Corinthians', 5, 1, '&nbsp;زۀ خبر شوے يم چې ستاسو په مينځ کښې جنسى حرام کارى کيږى، بلکې داسې جنسى حرام کارى چې په بې‌دينه خلقو کښې هم نۀ کيږى. په تاسو کښې يو سړے دے چې د هغۀ خپلې ميرنۍ مور سره ناجائزه تعلقات دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27323, '1 Corinthians 5:2', '1 Corinthians', 5, 2, '&nbsp;او تاسو پرې فخر کوئ. ولې تاسو ته په کار نۀ دى چې پرې وشرمېږئ؟ او چا چې دا کار کړے دے هغه د خپل مينځ نه وشړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27324, '1 Corinthians 5:3', '1 Corinthians', 5, 3, '&nbsp;زۀ اګر کۀ په جسمانى طور موجود نۀ يم خو په روحانى طور موجود يم. او په داسې کس ما داسې فېصله واوروله لکه چې زۀ تاسو سره موجود يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27325, '1 Corinthians 5:4', '1 Corinthians', 5, 4, '&nbsp;کله چې تاسو زمونږ د مالِک عيسىٰ په نوم راجمع شئ او زۀ تاسو سره په روح کښې موجود يم، او چې زمونږ د مالِک عيسىٰ قدرت هم راسره موجود وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27326, '1 Corinthians 5:5', '1 Corinthians', 5, 5, '&nbsp;نو تاسو دا سړے د هلاکت دپاره شېطان ته وسپارئ، نو د هغۀ ګناه ګار بدن به هلاک شى خو د هغۀ روح به د مالِک خُدائ د قيامت د راتلو په ورځ خلاصون بيا مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27327, '1 Corinthians 5:6', '1 Corinthians', 5, 6, '&nbsp;ستاسو فخر کول ښۀ خبره نۀ ده. ولې تاسو خبر نۀ يئ چې لږه شان خمبيره په قلپۍ کښې ټول اخښلے شوى اوړۀ خمبيره کوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27328, '1 Corinthians 5:7', '1 Corinthians', 5, 7, '&nbsp;خپل ځان نه زړه خمبيره وباسئ، نو چې تاسو لکه د تازه پتيره اوړو په شان جوړ شئ ځکه چې په حقيقت کښې تاسو د خمبيره اوړو په شان نۀ يئ، نو تاسو پاک يئ، ځکه چې مسيح د فسح اختر ګډُورے، زمونږ دپاره قربان شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27329, '1 Corinthians 5:8', '1 Corinthians', 5, 8, '&nbsp;نو راځئ چې مونږ اختر وکړُو، نۀ په زړه خمبيره او نۀ د بدۍ او نۀ د شرارت په خمبيره بلکې په صفا زړۀ او د رښتياو په پتيره روټۍ باندې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27330, '1 Corinthians 5:9', '1 Corinthians', 5, 9, '&nbsp;ما په خپل خط کښې تاسو ته دا ليکلى وُو چې د حرام کارو سره ناسته پاسته مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27331, '1 Corinthians 5:10', '1 Corinthians', 5, 10, '&nbsp;زما مطلب خو دا نۀ دے چې تاسو بلکل په خپل ژوند کښې د بې‌ايمانه، حرام کارو، لالچيانو، ظالمانو يا بُت پرستانو سره تعلق پرېږدئ، نو په داسې کولو خو به بيا تاسو دا دُنيا پرېښودلى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27332, '1 Corinthians 5:11', '1 Corinthians', 5, 11, '&nbsp;خو زۀ اوس تاسو ته دا ليکم چې کۀ څوک ځان ته ايماندار ورور يا خور وائى او حرام کار يا حرصناک يا بُت پرست يا کنځل مار يا شرابى يا ظالم وى نو د داسې کس سره روټۍ قدرې هم مۀ خورئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27333, '1 Corinthians 5:12', '1 Corinthians', 5, 12, '&nbsp;ځکه چې زما څۀ کار دے چې د هغوئ عدالت وکړم چې د جماعت نه بهر دى؟ خو تاسو د هغوئ عدالت کوئ څوک چې په جماعت کښې شامل دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27334, '1 Corinthians 5:13', '1 Corinthians', 5, 13, '&nbsp;خُدائ پاک به په خپله د هغوئ عدالت وکړى څوک چې مونږ نه بهر دى. ”هغه بد سړے د خپل مينځ نه وشړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27335, '1 Corinthians 6:1', '1 Corinthians', 6, 1, '&nbsp;ولې تاسو دا جرأت کوئ چې کله ستاسو د خپل ايماندار ورور سره مقدمه وى نو تاسو د فېصلې دپاره دا د بې‌دينه خلقو عدالت ته پېش کوئ او مقدسينو ته يې نۀ پېش کوئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27336, '1 Corinthians 6:2', '1 Corinthians', 6, 2, '&nbsp;ولې تاسو ته دا پته نشته چې مقدسين به د دُنيا عدالت کوى؟ نو چې تاسو به د دُنيا عدالت کوئ نو ولې تاسو د دې جوګه نۀ يئ چې د معمولى نه معمولى مقدمو فېصلې وکړئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27337, '1 Corinthians 6:3', '1 Corinthians', 6, 3, '&nbsp;ولې تاسو ته پته نشته چې مونږ به د فرښتو عدالت کوُو؟ نو بيا به تاسو عامې مقدمې نۀ شئ فېصله کولے څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27338, '1 Corinthians 6:4', '1 Corinthians', 6, 4, '&nbsp;نو کۀ ستاسو په مينځ کښې عامې مقدمې وى نو ولې تاسو هغه خلق منصفان مقرروئ چې په جماعت کښې د هغوئ څۀ حيثيت نۀ وى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27339, '1 Corinthians 6:5', '1 Corinthians', 6, 5, '&nbsp;تاسو ته زۀ دا د شرمولو دپاره وايم چې ولې په تاسو کښې څوک هم دومره هوښيار نشته چې هغه د دوو ايماندارانو په مينځ کښې فېصله وکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27340, '1 Corinthians 6:6', '1 Corinthians', 6, 6, '&nbsp;ځکه چې يو ايماندار د بل ايماندار خلاف عدالت ته ځى او هغه هم بې‌دينو خلقو له.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27341, '1 Corinthians 6:7', '1 Corinthians', 6, 7, '&nbsp;په حقيقت کښې په يو بل مقدمه کول ستاسو غلطى ده. آيا دا به ښۀ نۀ وه چې هغه نا اِنصافى مو برداشت کړے وے؟ او يا کۀ چا تاسو له دوکه درکړى وه او په هغې مو صبر کړے وے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27342, '1 Corinthians 6:8', '1 Corinthians', 6, 8, '&nbsp;خو تاسو په خپله ايماندارانو سره بد کوئ او ورله دوکه ورکوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27343, '1 Corinthians 6:9', '1 Corinthians', 6, 9, '&nbsp;ولې تاسو په دې خبر نۀ يئ چې بدکاران به د خُدائ پاک د بادشاهۍ وارثان نۀ شى؟ ځان مۀ دوکه کوئ، نۀ به حرام کار، نۀ بُت پرست، نۀ زناکار، نۀ بچه بازان،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27344, '1 Corinthians 6:10', '1 Corinthians', 6, 10, '&nbsp;نۀ غلۀ، نۀ حرصناک، نۀ شرابيان، نۀ کنځل مار او نۀ به دوکه مار د خُدائ پاک د بادشاهۍ وارثان شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27345, '1 Corinthians 6:11', '1 Corinthians', 6, 11, '&nbsp;او په تاسو کښې ځينې هم دغه شان وُو خو تاسو د مالِک عيسىٰ مسيح په نوم او زمونږ د خُدائ پاک په روح ووينځلے شوئ. بلکې پاک شوئ، صادق هم شوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27346, '1 Corinthians 6:12', '1 Corinthians', 6, 12, '&nbsp;ستاسو په خيال چې ټول څيزونه تاسو ته روا دى خو زۀ وايم چې ټول څيزونه فائده مند نۀ دى. کۀ تاسو ټول څيزونه ځان دپاره روا ګڼئ خو بيا هم خپل ځان د هغوئ غلام مۀ جوړَوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27347, '1 Corinthians 6:13', '1 Corinthians', 6, 13, '&nbsp;ستاسو په خيال چې خوراک د خېټې دپاره دے او خېټه د خوراک دپاره ده خو زۀ وايم چې خُدائ پاک به هغه دواړه ختم کړى. بدن د حرامکارۍ دپاره نۀ دے جوړ شوے بلکې د مالِک د خِدمت دپاره جوړ شوے دے او مالِک د بدن ساتونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27348, '1 Corinthians 6:14', '1 Corinthians', 6, 14, '&nbsp;خُدائ پاک مالِک هم بيا ژوندے کړو او مونږ به هم په خپل قُدرت سره بيا ژوندى کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27349, '1 Corinthians 6:15', '1 Corinthians', 6, 15, '&nbsp;ولې تاسو خبر نۀ يئ چې ستاسو بدنونه د مسيح اندامونه دى؟ نو ولې زۀ دې د مسيح اندامونو نه د يوې کنجرې اندامونه جوړ کړم؟ نه، هيڅکله نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27350, '1 Corinthians 6:16', '1 Corinthians', 6, 16, '&nbsp;ولې تاسو نۀ يئ خبر چې هر څوک چې کنجرې له لاړ شى نو هغه د هغې سره يو بدن شى؟ ځکه چې صحيفې وائى چې، ”دا دواړه به يو بدن شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27351, '1 Corinthians 6:17', '1 Corinthians', 6, 17, '&nbsp;خو هر څوک چې د مالِک سره پيوند شى، هغه به د مالِک سره يو روح شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27352, '1 Corinthians 6:18', '1 Corinthians', 6, 18, '&nbsp;د حرام کارۍ نه تښتئ. د انسان نه چې کومه ګناه کيږى هغه د بدن نه بهر وى د زنا نه بغېر، ځکه چې حرام کار خپل بدن هم تباه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27353, '1 Corinthians 6:19', '1 Corinthians', 6, 19, '&nbsp;ولې تاسو ته پته نشته چې ستاسو بدن د روحُ القُدس کور دے؟ څوک چې په تاسو کښې اوسيږى او هغه د خُدائ پاک د طرف نه تاسو ته درکړے شوے دے. نو اوس تاسو د خپل ځان مالِک نۀ يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27354, '1 Corinthians 6:20', '1 Corinthians', 6, 20, '&nbsp;ځکه چې خُدائ پاک تاسو په بيعه اخستى يئ، نو په دې وجه خپل بدن کښې خُدائ پاک ته جلال ورکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27355, '1 Corinthians 7:1', '1 Corinthians', 7, 1, '&nbsp;اوس د هغه مسئلو په حقله کومې چې تاسو ليکلى دى چې د سړى دپاره دا بهتره ده چې د ښځې سره کوروالے ونۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27356, '1 Corinthians 7:2', '1 Corinthians', 7, 2, '&nbsp;خو د حرام کارۍ نه د بچ کېدو د خاطره دا به ښۀ وى چې د هر سړى خپله ښځه وى او د هرې ښځې خپل خاوند وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27357, '1 Corinthians 7:3', '1 Corinthians', 7, 3, '&nbsp;خاوند دې د خپلې ښځې د کوروالى خيال ساتى او هم دغه شان دې ښځه د خپل خاوند خيال ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27358, '1 Corinthians 7:4', '1 Corinthians', 7, 4, '&nbsp;ښځه د خپل بدن اختيارمنده نۀ ده، بلکې اختيار د خاوند دے. هم دغه شان خاوند د خپل بدن اختيارمند نۀ دے بلکې د هغۀ ښځه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27359, '1 Corinthians 7:5', '1 Corinthians', 7, 5, '&nbsp;تاسو د يو بل سره کوروالے مۀ پرېږدئ خو د لږ وخت دپاره د يو بل په مشوره خير دے چې د دُعا خاص فرصت درته مِلاو شى، او د لږ وخت نه وروستو بيا يو ځائ شئ، هسې نه چې شېطان د نفس د کمزورۍ په وجه تاسو په آزمېښت کښې واچوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27360, '1 Corinthians 7:6', '1 Corinthians', 7, 6, '&nbsp;زۀ تاسو ته د دې اجازت درکوم خو حُکم نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27361, '1 Corinthians 7:7', '1 Corinthians', 7, 7, '&nbsp;زما دا خواهش دے چې هر څوک دې په دې مسئله کښې زما په شان ناوادۀ کړے وى خو د خُدائ پاک د طرف نه هر چا ته جدا جدا نعمت ورکړے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27362, '1 Corinthians 7:8', '1 Corinthians', 7, 8, '&nbsp;نو زۀ ناوادۀ کړو او کونډو ته دا وايم چې د هغوئ دپاره دا بهتره ده چې زما په شان ناوادۀ کړى پاتې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27363, '1 Corinthians 7:9', '1 Corinthians', 7, 9, '&nbsp;خو کۀ هغوئ خپل ځانونه نۀ شى قابو کولے نو وادۀ دې وکړى ځکه چې وادۀ کول په شهوت کښې د سوزېدو نه ښۀ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27364, '1 Corinthians 7:10', '1 Corinthians', 7, 10, '&nbsp;خو چې د چا وادۀ شوے وى هغوئ ته، زۀ نه، بلکې مالِک حکم ورکوى، چې ښځه دې د خپل خاوند نه نۀ جدا کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27365, '1 Corinthians 7:11', '1 Corinthians', 7, 11, '&nbsp;خو کۀ هغه جدا شى نو هغه دې بل خاوند ونۀ کړى يا دې د خپل خاوند سره دوباره پخلا شى، او خاوند دې هم د خپلې ښځې نه، نۀ تښتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27366, '1 Corinthians 7:12', '1 Corinthians', 7, 12, '&nbsp;دې نورو ته هم زۀ دا وايم، نه چې مالِک، کۀ د يو ايماندار ښځه ايمانداره نۀ وى او هغه د هغۀ سره په اوسېدو راضى وى نو هغه دې خپلې ښځې له طلاق نۀ ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27367, '1 Corinthians 7:13', '1 Corinthians', 7, 13, '&nbsp;او کۀ د کومې ښځې خاوند چې ايماندار نۀ وى او هغه د هغې سره په اوسېدو راضى وى نو هغه دې د خپل خاوند نه طلاق نۀ اخلى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27368, '1 Corinthians 7:14', '1 Corinthians', 7, 14, '&nbsp;ځکه چې کوم خاوند ايماندار نۀ وى، نو هغه د ښځې په وجه پاک شى او کومه ښځه چې ايمانداره نۀ وى، نو هغه د ايماندار خاوند په وجه پاکه شى، ګنې ستاسو بچى به ناپاک وُو خو اوس پاک دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27369, '1 Corinthians 7:15', '1 Corinthians', 7, 15, '&nbsp;خو کۀ بې‌ايمانه خاوند يا ښځه په خپلو کښې جدا کېدل غواړى نو پرېږدئ چې جدا شى. په داسې حالت کښې ايماندار خاوند يا ښځه د يو بل پابند نۀ دى، ځکه چې خُدائ پاک تاسو د سلامتۍ ژوند کولو دپاره رابللى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27370, '1 Corinthians 7:16', '1 Corinthians', 7, 16, '&nbsp;ولې چې اے ښځې، تۀ څۀ خبر يې، کېدے شى چې تۀ خپل خاوند بچ کړې. او اے سړيه، تۀ څۀ خبر يې، کېدے شى چې تۀ خپله ښځه بچ کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27371, '1 Corinthians 7:17', '1 Corinthians', 7, 17, '&nbsp;خو بيا هم هر يو کس ته په کار دى چې هغه شان ژوند تير کړى کوم چې مالِک ورته مقرر کړے دے او کوم ته چې خُدائ پاک تاسو رابللى يئ. په ټولو جماعتونو کښې زما دا دستور دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27372, '1 Corinthians 7:18', '1 Corinthians', 7, 18, '&nbsp;کۀ چرې څوک سنت شوى رابللے شوى وى نو هغوئ دې خپل ځانونه ناسنته نۀ ښکاره کوى، او کۀ چرې څوک ناسنته رابللے شوى وى نو هغوئ دې خپل ځانونه نۀ سنتوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27373, '1 Corinthians 7:19', '1 Corinthians', 7, 19, '&nbsp;ځکه چې په سنت او ناسنته کښې څۀ مطلب نشته بلکې د خُدائ پاک په حکمونو عمل کول ضرورى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27374, '1 Corinthians 7:20', '1 Corinthians', 7, 20, '&nbsp;تاسو هر يو چې په کوم حالت کښې رابللے شوى يئ هم په هغې کښې پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27375, '1 Corinthians 7:21', '1 Corinthians', 7, 21, '&nbsp;آيا تۀ غلام وې کله چې راوبللے شوې؟ نو په دې مۀ پرېشانه کېږه، خو کۀ تا ته د آزادېدو موقع مِلاو شى نو هغه اختيار کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27376, '1 Corinthians 7:22', '1 Corinthians', 7, 22, '&nbsp;ځکه کۀ تاسو د غلامۍ په حالت کښې مالِک ته رابللے شوى يئ، نو په مالِک کښې آزاد کړے شوى يئ. دغه شان څوک چې آزاد رابللے شوے دے، هغه اوس د مسيح غلام دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27377, '1 Corinthians 7:23', '1 Corinthians', 7, 23, '&nbsp;تاسو په بيعه اخستے شوى يئ، نو اوس د انسانانو غلامان مۀ جوړېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27378, '1 Corinthians 7:24', '1 Corinthians', 7, 24, '&nbsp;اے وروڼو او خوېندو، په کوم حالت کښې چې تاسو رابللے شوى وئ، هم په هغې کښې د خُدائ پاک سره قائم پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27379, '1 Corinthians 7:25', '1 Corinthians', 7, 25, '&nbsp;خو د پېغلو په باب کښې ما سره د مالِک څۀ حکم نشته، خو زۀ څوک چې مالِک د خپل رحم په وسيله د اعتماد قابل کړے يم تاسو ته خپله رائے درکوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27380, '1 Corinthians 7:26', '1 Corinthians', 7, 26, '&nbsp;زما په خيال چې په دې سخت حالت کښې تاسو دپاره دا بهتره ده چې څنګه يئ هم هغه شان پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27381, '1 Corinthians 7:27', '1 Corinthians', 7, 27, '&nbsp;کۀ ستا ښځه وى نو هغې له د طلاق ورکولو کوشش مۀ کوه او کۀ ستا ښځه نۀ وى نو د وادۀ کولو کوشش مۀ کوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27382, '1 Corinthians 7:28', '1 Corinthians', 7, 28, '&nbsp;خو کۀ تۀ وادۀ وکړې نو تا ګناه نۀ ده کړې، او کۀ يوه پېغله وادۀ شى نو هغې څۀ ګناه ونۀ کړه، خو کۀ څوک وادۀ وکړى نو په ژوند کښې به پرې تکليفونه راشى او زۀ تاسو د دې نه بچ کول غواړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27383, '1 Corinthians 7:29', '1 Corinthians', 7, 29, '&nbsp;خو اے وروڼو او خوېندو، زۀ دا وايم چې مقرر شوے وخت رانزدې دے نو د دې نه پس دې د ښځو خاوندان داسې وى لکه چې د هغوئ ښځې نۀ وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27384, '1 Corinthians 7:30', '1 Corinthians', 7, 30, '&nbsp;او ژړېدونکى دې داسې وى لکه چې هغوئ نۀ ژړل، او څوک چې خوشحالى کوى، هغوئ دې داسې وى لکه چې هغوئ خوشحالى نۀ کوى، او اخستونکى دې داسې وى لکه چې مال ورسره نۀ وى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27385, '1 Corinthians 7:31', '1 Corinthians', 7, 31, '&nbsp;او څوک چې د دُنيا سره لېن دېن کوى هغوئ دې داسې وى لکه دې سره يې هيڅ لېن دېن نۀ وى. ځکه چې دا موجوده دُنيا فنا کېدونکې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27386, '1 Corinthians 7:32', '1 Corinthians', 7, 32, '&nbsp;زۀ دا غواړم چې تاسو د پرېشانۍ نه بې‌غمه اوسئ. ناوادۀ شوے سړے د مالِک په حقله سوچ کوى چې مالِک به څنګه راضى کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27387, '1 Corinthians 7:33', '1 Corinthians', 7, 33, '&nbsp;خو وادۀ شوے سړے د دُنياوى څيزونو په حقله سوچ کوى چې خپله ښځه به څنګه راضى کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27388, '1 Corinthians 7:34', '1 Corinthians', 7, 34, '&nbsp;او هغه دوه زړيه شى. خو ناوادۀ شوې ښځه او پېغله د مالِک په فکر کښې اوسيږى چې د هغوئ بدن او روح دواړه پاک شى، خو وادۀ شوې ښځه د دُنياوى څيزونو په حقله فکر کوى چې څنګه به خپل خاوند راضى کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27389, '1 Corinthians 7:35', '1 Corinthians', 7, 35, '&nbsp;زۀ دا ستاسو د فائدې دپاره وايم، نه چې په تاسو څۀ پابندۍ دپاره بلکې څۀ چې ښۀ وى په هغې عمل وکړئ او تاسو د مالِک په خِدمت کښې بې‌غمه آخته اوسئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27390, '1 Corinthians 7:36', '1 Corinthians', 7, 36, '&nbsp;کۀ د چا دا خيال وى چې هغه د خپلې چنغلې سره د وادۀ نۀ کولو په وجه د هغې حق وهى او د هغې زيات خواهشمند وى نو پرېږدئ چې د هغې سره وادۀ وکړى نو دا ګناه نۀ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27391, '1 Corinthians 7:37', '1 Corinthians', 7, 37, '&nbsp;خو کۀ چا خپل ځان سره د وادۀ نۀ کولو پخه اراده کړې وى او هغه مجبوره نۀ وى بلکې خپل خواهش ساتلے شى او په زړۀ کښې يې دا وى چې خپله چنغله به بې‌وادۀ نۀ پرېږدى نو هغه ښۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27392, '1 Corinthians 7:38', '1 Corinthians', 7, 38, '&nbsp;نو بيا څوک چې د خپلې چنغلې سره وادۀ کوى هغه ښۀ کوى، او څوک يې چې نۀ کوى هغه لا ښۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27393, '1 Corinthians 7:39', '1 Corinthians', 7, 39, '&nbsp;د يوې ښځې چې ترڅو خاوند ژوندے وى هغه تر هغې د هغۀ پابنده ده، خو کۀ خاوند يې مړ شى نو هغه بيا آزاده ده خو صرف د ايماندار سره وادۀ کولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27394, '1 Corinthians 7:40', '1 Corinthians', 7, 40, '&nbsp;خو زما په خيال به هغه بختوره وى چې په خپل حالت کښې پاتې شى څنګه چې ده، او زما په خيال چې د خُدائ پاک د روح په مطابق تاسو ته زۀ دا نصيحت کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27395, '1 Corinthians 8:1', '1 Corinthians', 8, 1, '&nbsp;کوم سوال چې تاسو ته د هغه خوراک په حقله کوم چې بُتانو ته پېش کيږى پېدا شوے دے، جواب يې دا دے چې مونږ ټول خو د دې موضوع په حقله عِلم لرو. خو عِلم مونږ مغروره کوى، او مينه مونږ جوړوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27396, '1 Corinthians 8:2', '1 Corinthians', 8, 2, '&nbsp;کۀ څوک دا وائى چې زۀ پوهه يم نو څنګه چې پوهېدل په کار دى هغه شان لا نۀ پوهيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27397, '1 Corinthians 8:3', '1 Corinthians', 8, 3, '&nbsp;خو څوک چې د خُدائ پاک سره مينه کوى خُدائ پاک په خپله هغه پېژنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27398, '1 Corinthians 8:4', '1 Corinthians', 8, 4, '&nbsp;نو بُتانو ته د پېش کړے شوى خوراک د خوړلو په حقله مونږ پوهيږو چې په بُت کښې هيڅ رښتينوالے نشته او بغېر د يو خُدائ پاک نه بل نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27399, '1 Corinthians 8:5', '1 Corinthians', 8, 5, '&nbsp;کۀ خلق په زمکه او په آسمان کښې ډېر معبودان او ډېر خُدايان او مالِکان منى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27400, '1 Corinthians 8:6', '1 Corinthians', 8, 6, '&nbsp;خو زمونږ دپاره يو خُدائ پاک دے، يعنې پلار، او څوک چې د ټولو څيزونو خالق دے او د چا دپاره چې مونږ ژوندى يُو، او يو مالِک دے، يعنې عيسىٰ مسيح څوک چې د ټولو څيزونو خالق دے او د چا په وسيله چې مونږ ژوندى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');